base = {int(r["id"]): r for r in csv.DictReader(open(os.path.join(D, "eval_questions.csv"), encoding="utf-8-sig"))}
rows = []
n = 0
for bid in range(1, 51):
    b = base[bid]
    for k, (st, qtext) in enumerate(zip(STYLES, P[bid])):
        n += 1
        rows.append(dict(id=f"P{n:03d}", 그룹="변형", 원문id=bid, 변형유형=st, 질문=qtext, 기준질문=b["질문"],
                         정답_핵심=b["정답_핵심"], 근거조항=b["근거조항"], 답변가능여부=b["답변가능여부"]))
n = 0
for bid in range(1, 51):
    b = base[bid]
    for k, (st, qtext) in enumerate(zip(STYLES, P[bid])):
        n += 1
        t, kinds = add_typos(qtext, seed=bid * 100 + k)
        rows.append(dict(id=f"T{n:03d}", 그룹="오타", 원문id=bid, 변형유형=f"{st}|{kinds}", 질문=t, 기준질문=qtext,
                         정답_핵심=b["정답_핵심"], 근거조항=b["근거조항"], 답변가능여부=b["답변가능여부"]))
assert len(rows) == 600 and len({r["질문"] for r in rows}) == 600
with open(os.path.join(D, "eval_600.csv"), "w", encoding="utf-8-sig", newline="") as f:
    w = csv.DictWriter(f, fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
json.dump(rows, open(os.path.join(D, "eval_600.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
